using System;
using System.Collections.Generic;
using LootEdit;
using LootEdit.loot;
using Microsoft.Xna.Framework;
using ProjectTower.character;
using ProjectTower.gamestate;
using ProjectTower.player;

namespace ProjectTower.map.pickups;

public class Pickup
{
	public int ID;

	public bool exists;

	public Vector2 loc;

	public InvLoot[] loot;

	public string flag;

	public bool isSharedDrop;

	public bool droppedByCharacter;

	private const string PICKED_UP = "_pkp";

	public Pickup(int ID)
	{
		this.ID = ID;
		exists = false;
	}

	public void CheckIsShared()
	{
		isSharedDrop = true;
		for (int i = 0; i < loot.Length; i++)
		{
			LootDef lootDef = LootCatalog.category[loot[i].category].loot[loot[i].catalogIdx];
			switch (loot[i].category)
			{
			case 6:
				isSharedDrop = true;
				break;
			case 7:
				if (lootDef.type != 7)
				{
					if (lootDef.flags == 14)
					{
						isSharedDrop = true;
					}
					int type = lootDef.type;
					if (((uint)type <= 2u || (uint)(type - 4) <= 2u) && lootDef.flags == 3)
					{
						isSharedDrop = true;
					}
				}
				break;
			}
		}
	}

	public void AddToInv(Player p)
	{
		for (int i = 0; i < loot.Length; i++)
		{
			if (p.pickup == null)
			{
				p.pickupFrame = 3f;
				p.pickup = new List<Player.PlayerPickup>();
			}
			InvLoot invLoot = new InvLoot(loot[i]);
			if (invLoot.category == 5)
			{
				LootDef lDef = LootCatalog.category[loot[i].category].loot[loot[i].catalogIdx];
				if (Magic.GetPlayerAlreadyHas(p, lDef, loot[i].catalogIdx))
				{
					invLoot = new InvLoot();
					invLoot.InitFromName("salt1");
				}
			}
			if (this.flag != null)
			{
				if ((this.flag == "#chp#" && p.ID != GameStateManager.coopPlayerIdx) || (this.flag == "#mhp#" && p.ID != GameStateManager.mainPlayerIdx))
				{
					return;
				}
				if (p.flags.Contains(this.flag + "_pkp"))
				{
					invLoot = new InvLoot();
					invLoot.InitFromName("salt1");
				}
			}
			if (p.ID == GameStateManager.coopPlayerIdx)
			{
				LootDef lootDef = LootCatalog.category[loot[i].category].loot[loot[i].catalogIdx];
				if ((lootDef.category != 7 || lootDef.type != 7) && !isSharedDrop)
				{
					invLoot = new InvLoot();
					if (Rand.CoinToss(0.5f))
					{
						invLoot.InitFromName("salt1");
					}
					else
					{
						invLoot.InitFromName("health_shard");
					}
				}
			}
			int num = p.playerInv.Add(invLoot, autoSelect: true, invLoot.count);
			if (num > -1)
			{
				if (p.pickupFrame < 0.25f)
				{
					p.pickupFrame = 3f - p.pickupFrame;
				}
				else if (p.pickupFrame < 2.75f)
				{
					p.pickupFrame = 2.75f;
				}
				p.AddPickup(num, invLoot.category, invLoot.catalogIdx, invLoot.count);
				continue;
			}
			Character playerCharacter = CharMgr.GetPlayerCharacter(p);
			if (playerCharacter != null)
			{
				string text = LootCatalog.category[loot[i].category].loot[loot[i].catalogIdx].name;
				if (loot[i].count > 1)
				{
					text = text + "/" + loot[i].count;
				}
				bool flag = exists;
				if (!exists)
				{
					exists = true;
				}
				int num2 = MapMgr.pickupMgr.Drop(new string[1] { text }, playerCharacter.loc + new Vector2(0f, -50f), (p.ID == GameStateManager.mainPlayerIdx) ? "#mhp#" : "#chp#");
				if (num2 > -1)
				{
					MapMgr.pickupMgr.pickup[num2].droppedByCharacter = droppedByCharacter;
					MapMgr.pickupMgr.pickup[num2].isSharedDrop = isSharedDrop;
				}
				exists = flag;
			}
		}
		if (this.flag != null && !(this.flag == "#mhp#") && !(this.flag == "#chp#") && (p.ID != GameStateManager.coopPlayerIdx || isSharedDrop) && !p.flags.Contains(this.flag + "_pkp"))
		{
			p.flags.Add(this.flag + "_pkp");
		}
		exists = false;
	}

	public void Set(string[] drops, Vector2 loc, string flag)
	{
		exists = true;
		this.loc = loc;
		loot = new InvLoot[drops.Length];
		this.flag = flag;
		droppedByCharacter = false;
		for (int i = 0; i < drops.Length; i++)
		{
			if (drops[i].Contains("/"))
			{
				loot[i] = new InvLoot();
				string[] array = drops[i].Split('/');
				loot[i].InitFromName(array[0]);
				loot[i].count = Convert.ToInt32(array[1]);
			}
			else
			{
				loot[i] = new InvLoot();
				loot[i].InitFromName(drops[i]);
			}
		}
		if (CharCols.TestCol(this.loc, falling: true, 0f))
		{
			Character playerCharacter = CharMgr.GetPlayerCharacter(PlayerMgr.GetMainPlayer());
			if (playerCharacter != null)
			{
				Vector2 vector = playerCharacter.loc - this.loc;
				if (vector.X != 0f && vector.Y != 0f)
				{
					vector.Normalize();
					for (int j = 0; j < 32; j++)
					{
						this.loc += vector * 32f;
						if (!CharCols.TestCol(this.loc, falling: true, 0f))
						{
							break;
						}
					}
				}
			}
		}
		CheckIsShared();
	}
}
