using Microsoft.Xna.Framework;
using ProjectTower.character;
using ProjectTower.gamestate;
using ProjectTower.particles;
using ProjectTower.player;

namespace ProjectTower.map.pickups;

public class PickupMgr
{
	public Pickup[] pickup;

	private float frame;

	public const int MAX_PICKUPS = 256;

	public PickupMgr()
	{
		pickup = new Pickup[256];
		for (int i = 0; i < pickup.Length; i++)
		{
			pickup[i] = new Pickup(i);
		}
	}

	public int Drop(string[] drops, Vector2 loc, string flag)
	{
		for (int i = 0; i < pickup.Length; i++)
		{
			if (!pickup[i].exists)
			{
				pickup[i].Set(drops, loc, flag);
				return i;
			}
		}
		return -1;
	}

	public void Update()
	{
		frame += Game1.frameTime;
		if (!(frame > 1f / 60f))
		{
			return;
		}
		frame -= 1f / 60f;
		for (int i = 0; i < pickup.Length; i++)
		{
			if (pickup[i].exists)
			{
				ParticleManager.AddBackAdditiveParticle(16, pickup[i].loc, default, 1f, 0f, -1, -1);
				ParticleManager.AddAdditiveParticle(16, pickup[i].loc, default, 1f, 0f, -1, -1);
				ParticleManager.AddBackAdditiveParticle(17, pickup[i].loc, Rand.GetRandomVec2(0f, 50f, -200f, 0f), Rand.GetRandomFloat(0.1f, 0.5f), 0f, -1, -1);
				Vector2 loc = pickup[i].loc;
				pickup[i].loc.Y += 3f;
				if (CharCols.TestCol(pickup[i].loc + new Vector2(0f, 44f), falling: true, 0f))
				{
					pickup[i].loc = loc;
				}
			}
		}
	}

	public int GetPickup(Player p)
	{
		Character playerCharacter = CharMgr.GetPlayerCharacter(p);
		float num = 120f;
		if (playerCharacter != null && playerCharacter.state == 0)
		{
			for (int i = 0; i < pickup.Length; i++)
			{
				if (pickup[i].exists && pickup[i].loc.Y < playerCharacter.loc.Y + 64f && pickup[i].loc.Y > playerCharacter.loc.Y - 64f && playerCharacter.loc.X < pickup[i].loc.X + num && playerCharacter.loc.X > pickup[i].loc.X - num)
				{
					return i;
				}
			}
		}
		return -1;
	}

	internal void DropAndPickup(string[] drops, string flag)
	{
		if (GameStateManager.GetMainPlayer() == null)
		{
			return;
		}
		for (int i = 0; i < pickup.Length; i++)
		{
			if (!pickup[i].exists)
			{
				pickup[i].Set(drops, default, flag);
				pickup[i].isSharedDrop = true;
				pickup[i].AddToInv(PlayerMgr.GetMainPlayer());
				if (GameStateManager.coopPlayerIdx > -1)
				{
					pickup[i].AddToInv(PlayerMgr.GetCoopPlayer());
				}
				pickup[i].exists = false;
				break;
			}
		}
	}
}
