	private void MoveMapChartoReserve(Character character)
	{
		if (DebugMgr.verboseReserve)
		{
			GameConsole.WriteLine(MonsterCatalog.catalog[character.monsterIdx].name + " removed. " + character.loc.ToString());
		}
		for (int i = 0; i < reserveChar.Length; i++)
		{
			if (reserveChar[i].exists)
			{
				continue;
			}
			reserveChar[i].InitFromCharacter(character);
			if (reserveChar[i].exists)
			{
				if (reserveChar[i].mapIdx > -1)
				{
					MapMgr.entityScript[reserveChar[i].mapIdx].charIdx = -1;
					MapMgr.entityScript[reserveChar[i].mapIdx].reserveCharIdx = i;
				}
				PlayerMgr.CheckReserveSaltChar(character.origVec);
			}
			return;
		}
		GameConsole.WriteLine("Out of reserve characters.");
	}

	private void MoveMapSmashabletoReserve(Smashable smashable)
	{
		for (int i = 0; i < reserveSmashable.Length; i++)
		{
			if (!reserveSmashable[i].exists)
			{
				reserveSmashable[i].InitFromSmashable(smashable);
				return;
			}
		}
		GameConsole.WriteLine("Out of reserve smashables.");
	}

